matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Adjust shared memory layout to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];  // Padding to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];  // Padding to avoid bank conflicts

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles into shared memory
        int A_col = tile * TILE_SIZE + threadIdx.x;
        int B_row = tile * TILE_SIZE + threadIdx.y;

        if (row < N && A_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + A_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (B_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[B_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with loop unrolling and warp-level optimization
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
            sum += As[threadIdx.y][k + 1] * Bs[k + 1][threadIdx.x];
            sum += As[threadIdx.y][k + 2] * Bs[k + 2][threadIdx.x];
            sum += As[threadIdx.y][k + 3] * Bs[k + 3][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

